-- Seed top 10 league clubs as vacant selectable clubs for manager registration.
-- Safe to run more than once: existing registered clubs with these keys are left untouched.

on conflict (key) do update
set data = excluded.data
where
  coalesce(public.clubs.data->>'manager', '') ilike '%vacante%'
  or coalesce(public.clubs.data->>'manager', '') ilike '%por inscribir%';
